export function summarizeMicrogrid187() {
  const m = microgridModule187;
  const values = Object.values(m).map((x: any) => x.value as number);
  const total = values.reduce((a, b) => a + b, 0);
  return { count: values.length, total, avg: total / (values.length || 1), domain: 'microgrid' };
}

